const BY_NAME = new Map(COUNTRY_FLAGS.map((c) => [c.name.toLowerCase(), c.code]))

// Exact (case-insensitive) name -> flag code, or null if we have no built-in flag.
export function flagCodeForCountry(name) {
  return name ? BY_NAME.get(name.trim().toLowerCase()) || null : null
}

// Public URL of the built-in flag for a country name, or '' if none.
export function flagUrlForCountry(name) {
  const code = flagCodeForCountry(name)
  return code ? `/flags/lib/${code}.svg` : ''
}
